68	const roundInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
69	
70	const BLOCK_SIZE = 3;
71	const BLOCK_BASE_PREMIUM = 60;
72	
73	const countByType = (items: Item[]): Map<string, number> => {
74	  const counts = new Map<string, number>();
75	  for (const item of items) {
76	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
77	  }
78	  return counts;
79	};
80	
81	const basePremiumForGroup = (type: string, count: number): number =>
82	  count === BLOCK_SIZE
83	    ? BLOCK_BASE_PREMIUM
84	    : count * ITEM_BASE_PREMIUMS[type];
85	
86	const policyBasePremium = (items: Item[]): number =>
87	  [...countByType(items)].reduce(
88	    (total, [type, count]) => total + basePremiumForGroup(type, count),
89	    0,
90	  );
91	
92	type SurchargeRule = {
93	  appliesTo: (item: Item) => boolean;
94	  rate: number;
95	};
96	
97	const SURCHARGE_RULES: SurchargeRule[] = [
98	  {
99	    appliesTo: (item) => item.cursed === true,
100	    rate: CURSE_SURCHARGE,
101	  },
102	  {
103	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
104	    rate: HIGH_ENCHANTMENT_SURCHARGE,
105	  },
106	];
107	
108	const itemSurcharge = (item: Item): number => {
109	  const itemBasePremium = ITEM_BASE_PREMIUMS[item.type];
110	  return SURCHARGE_RULES.filter((rule) => rule.appliesTo(item)).reduce(
111	    (surcharge, rule) => surcharge + itemBasePremium * rule.rate,
112	    0,
113	  );
114	};
115	
116	const sumItemSurcharges = (items: Item[]): number =>
117	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
118	
119	type PolicyContext = {
120	  customer: Customer;
121	  isFollowUpContract: boolean;
122	};
123	
124	type PolicyModifierRule = {
125	  appliesTo: (context: PolicyContext) => boolean;
126	  /** Signed rate applied to the policy base premium: positive adds, negative discounts. */
127	  rate: number;
128	};
129	
130	const POLICY_MODIFIER_RULES: PolicyModifierRule[] = [
131	  {
132	    appliesTo: () => true,
133	    rate: FIRST_INSURANCE_SURCHARGE,
134	  },
135	  {
136	    appliesTo: ({ customer }) =>
137	      customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
138	    rate: -LOYALTY_DISCOUNT,
139	  },
140	  {
141	    appliesTo: ({ isFollowUpContract }) => isFollowUpContract,
142	    rate: -FOLLOW_UP_CONTRACT_DISCOUNT,
143	  },
144	];
145	
146	const sumPolicyModifiers = (
147	  basePremium: number,
148	  context: PolicyContext,
149	): number =>
150	  POLICY_MODIFIER_RULES.filter((rule) => rule.appliesTo(context)).reduce(
151	    (total, rule) => total + basePremium * rule.rate,
152	    0,
153	  );
154	
155	const quotePremium = (items: Item[], context: PolicyContext): number => {
156	  const basePremium = policyBasePremium(items);
157	  return roundInMHPCOsFavour(
158	    basePremium +
159	      sumItemSurcharges(items) +
160	      sumPolicyModifiers(basePremium, context) +
161	      PROCESSING_FEE,
162	  );
163	};
164	
165	const insuranceSum = (items: Item[]): number =>
166	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
167	
168	const claimPayout = (damages: Damage[]): number =>
169	  damages.reduce((sum, damage) => sum + damage.amount - DEDUCTIBLE, 0);
170	
171	export const runScenario = (scenario: Scenario): ScenarioResults => {
172	  const remainingCaps = new Map<number, number>();
173	
174	  const results = scenario.steps.map((step, index) => {
175	    if (step.op === "quote") {
176	      remainingCaps.set(index, insuranceSum(step.items) * CAP_MULTIPLIER);
177	      return {
178	        premium: quotePremium(step.items, {
179	          customer: scenario.customer,
180	          isFollowUpContract: index > 0,
181	        }),
182	      };
183	    }
184	
185	    const payout = claimPayout(step.incident.damages);
186	    const remainingCap = (remainingCaps.get(step.policy) ?? 0) - payout;
187	    remainingCaps.set(step.policy, remainingCap);
188	    return { payout, remainingCap };
189	  });
190	
191	  return { results };
192	};
