export const runScenario = (scenario: Scenario): ScenarioResults => {
  const remainingCaps = new Map<number, number>();

  const results = scenario.steps.map((step, index) => {
    if (step.op === "quote") {
      remainingCaps.set(index, insuranceSum(step.items) * CAP_MULTIPLIER);
      return {
        premium: quotePremium(step.items, {
          customer: scenario.customer,
          isFollowUpContract: index > 0,
        }),
      };
    }

    const payout = claimPayout(step.incident.damages);
    const remainingCap = (remainingCaps.get(step.policy) ?? 0) - payout;
    remainingCaps.set(step.policy, remainingCap);
    return { payout, remainingCap };
  });

  return { results };
};

